def transform(grid):
    h,w=len(grid),len(grid[0]); objs=[]
    for color in range(1,10):
        pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==color]
        if pts: objs.append((min(c for r,c in pts),color,pts))
    objs.sort(); out=[[0]*w for _ in range(h)]
    anchors=[(0,0),(2,1),(3,2),(4,3)]
    for i,(_,color,pts) in enumerate(objs):
        mr=min(r for r,c in pts); mc=min(c for r,c in pts)
        ar,ac=anchors[i] if i<len(anchors) else (i+1,i)
        for r,c in pts:
            rr=ar+r-mr; cc=ac+c-mc
            if rr<h and cc<w: out[rr][cc]=color
    return out
