def transform(grid):
    h, w = len(grid), len(grid[0])
    objs = []
    for color in range(1, 10):
        cells = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == color]
        if cells:
            r0 = min(r for r,c in cells); c0 = min(c for r,c in cells)
            objs.append((min(c for r,c in cells), color, [(r-r0,c-c0) for r,c in cells]))
    objs.sort()
    out = [[0]*w for _ in range(h)]
    r0 = c0 = 0
    for i, (_, color, shape) in enumerate(objs):
        for r,c in shape:
            if r0+r < h and c0+c < w: out[r0+r][c0+c] = color
        if i+1 < len(objs):
            prev = shape
            # next upper-left sits diagonally at lower-left/rightward corner of prior figure
            r0 += max(r for r,c in prev)
            c0 += max(c for r,c in prev)
    return out

